timings={'setup_seconds':0,'setup':'warm env.sh worked; no install','npm_reported_seconds':0.515,'nproc':5,'baseline_binary_seconds':90.029,'family_binary_runs':[elapsed('timing-family-'+str(i)) for i in [1,2,3]],'family_median':med,'random_binary_runs':[elapsed('timing-random-'+str(i)) for i in [1,2,3]],'random_median':rand,'build_wall_seconds':{c['label']:c['seconds'] for c in commands if c['label'].endswith('-build')},'matrix_binary_seconds':{n:elapsed(n) for n in ['M1','M2','M3','P1']}}
